const title = document.querySelector("h1");
title.textContent = "Shop.mn — Монголын онлайн дэлгүүр";

document.querySelector('[data-testid="cart-count"]').textContent = "0";

const products = [
  { id: 1, name: "Монгол дээл", price: 129000, image: "images/deel.jpg" },
  { id: 2, name: "Малгай", price: 45000, image: "images/malgai.jpg" },
  { id: 3, name: "Гутал", price: 89000, image: "images/gutal.jpg" },
];

function formatPrice(value) {
  return "₮ " + value.toLocaleString("en-US");
}

const grid = document.querySelector('[data-testid="grid"]');

products.forEach(function (product) {
  const cardEl = document.createElement("article");
  cardEl.className = "product-card";

  const image = document.createElement("img");
  image.src = product.image;
  image.alt = product.name;

  const name = document.createElement("h3");
  name.textContent = product.name;

  const price = document.createElement("p");
  price.className = "price";
  price.textContent = formatPrice(product.price);

  const button = document.createElement("button");
  button.className = "btn-add";
  button.dataset.testid = "add-to-cart";
  button.textContent = "Сагсанд хийх";

  cardEl.append(image, name, price, button);
  grid.append(cardEl);
});

const cart = [];

function addToCart(product) {
  const existing = cart.find(function (item) {
    return item.id === product.id;
  });

  if (existing) {
    existing.quantity += 1;
  } else {
    cart.push({ id: product.id, name: product.name, quantity: 1 });
  }

  renderCart();
}

function renderCart() {
  const list = document.querySelector('[data-testid="cart-items"]');
  list.textContent = "";

  let total = 0;
  cart.forEach(function (item) {
    total += item.quantity;
    const row = document.createElement("li");
    row.textContent = item.name + " × " + item.quantity;
    list.append(row);
  });

  document.querySelector('[data-testid="cart-count"]').textContent = String(total);
}

const buttons = document.querySelectorAll('[data-testid="add-to-cart"]');
buttons.forEach(function (button, index) {
  button.addEventListener("click", function () {
    addToCart(products[index]);
  });
});

/* Shop.mn-ийн загвар */

body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
}

h1 { font-size: 36px; }

header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
}

.cart-count {
  background-color: #2563eb;
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}

.search,
.sort {
  padding: 10px 12px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  font-size: 16px;
  background-color: #ffffff;
  color: #18181b;
}

.search { flex: 1 1 220px; }

.product-card {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}

.product-card img {
  width: 100%;
  height: auto;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 8px;
}

header img { width: 96px; height: auto; }

.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

.product-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

.cart ul {
  list-style: none;
  padding: 0;
}

.cart li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid #e4e4e7;
}

@media (min-width: 768px) {
  .product-grid { grid-template-columns: 1fr 1fr; }
  header { flex-direction: row; justify-content: space-between; }
}

