    if (String(url).endsWith("/api/products") && method === "GET") {
      return json(window.API_EMPTY ? [] : products);
    }

    // Барааг устгах: DELETE /api/products/:id
    if (method === "DELETE" && String(url).includes("/api/products/")) {
      const id = Number(String(url).split("/").pop());
      const index = products.findIndex((p) => p.id === id);
      if (index !== -1) {
        products.splice(index, 1);
      }
      return json({ ok: true });
    }

    if (String(url).endsWith("/api/orders") && method === "GET") {
      return json(orders);
    }

    if (String(url).endsWith("/api/orders") && method === "POST") {
      const order = JSON.parse(options.body);
      if (!order.items || order.items.length === 0) {
        return json({ error: "Сагс хоосон байна" }, 400);
      }
      const saved = { id: orders.length + 1, ...order };
      orders.push(saved);
      return json(saved, 201);
    }

    return json({ error: "Хаяг олдсонгүй" }, 404);
  };
})();

