// Shop.mn-ий сервер. Энэ функц жинхэнэ сервер дээр ч яг ийм л харагдана:
// хүсэлт (Request) авч, хариу (Response) буцаана.

// Хариу бүрийг JSON болгож буцаах жижиг туслах.
function json(body, status) {
  return new Response(JSON.stringify(body), {
    status: status || 200,
    headers: { "Content-Type": "application/json" },
  });
}

async function handleRequest(request) {
  const path = new URL(request.url).pathname;

  if (path === "/api/products" && request.method === "GET") {
    return json(db.products);
  }

  const productMatch = path.match(/^\/api\/products\/(\d+)$/);
  if (productMatch && request.method === "DELETE") {
    const id = Number(productMatch[1]);
    const index = db.products.findIndex((item) => item.id === id);
    if (index === -1) {
      return json({ error: "Бараа олдсонгүй" }, 404);
    }
    db.products.splice(index, 1);
    return json({ ok: true, id: id });
  }

  return json({ error: "Хаяг олдсонгүй: " + path }, 404);
}

// Tier 1-д модуль байхгүй тул handleRequest-ээ ил гаргаж өгнө.
// Жинхэнэ сервер дээр энэ мөрийн оронд "export default" бичигдэнэ.
window.handleRequest = handleRequest;

