// Замын төрлөөс хамааруулж Cache-Control-ийн утгыг буцаана.
function cacheControlFor(path) {
  // Статик файлын нэрд hash явдаг тул агуулга нь хэзээ ч өөрчлөгдөхгүй → удаан кэшлэнэ.
  if (path.startsWith("/static/")) {
    return "public, max-age=" + ONE_YEAR + ", immutable";
  }
  // API-ийн өгөгдөл байнга өөрчлөгддөг → огт кэшлэхгүй.
  return "no-store";
}

function json(body, path, status) {
  return new Response(JSON.stringify(body), {
    status: status || 200,
    headers: {
      "Content-Type": "application/json",
      "Cache-Control": cacheControlFor(path),
    },
  });
}

function asset(path) {
  const file = ASSETS[path];
  return new Response(file.body, {
    status: 200,
    headers: {
      "Content-Type": file.type,
      "Cache-Control": cacheControlFor(path),
    },
  });
}

async function handleRequest(request) {
  const path = new URL(request.url).pathname;

  if (ASSETS[path] && request.method === "GET") {
    return asset(path);
  }

  if (path === "/api/products" && request.method === "GET") {
    return json(db.products, path);
  }

  return json({ error: "Хаяг олдсонгүй: " + path }, path, 404);
