    } catch (problem) {
      setError(problem.message);
    } finally {
      setLoading(false);
    }
  }

  async function createProduct(event) {
    event.preventDefault();

    const price = Number(priceInput);
    if (name.trim().length < 2 || !Number.isFinite(price) || price <= 0) {
      setFormError("Нэр 2-оос урт, үнэ эерэг тоо байх ёстой.");
      return;
    }

    setFormError(null);
    setSaving(true);

    try {
      const response = await fetch(API, {
        method: "POST",
        headers: authHeaders({ "Content-Type": "application/json" }),
        body: JSON.stringify({ name: name.trim(), price: price }),
      });

      if (!response.ok) {
        const body = await response.json();
        throw new Error(body.error || "Хадгалж чадсангүй");
      }

      setName("");
      setPriceInput("");
      await loadProducts();
    } catch (problem) {
      setFormError(problem.message);
    } finally {
      setSaving(false);
    }
  }

  async function deleteProduct(id) {
    setError(null);

    try {
      const response = await fetch(API + "/" + id, {
        method: "DELETE",
        headers: authHeaders(),
      });

      if (!response.ok) {
        throw new Error("Устгаж чадсангүй (" + response.status + ")");
      }

      setConfirmId(null);
      await loadProducts();
    } catch (problem) {
      setError(problem.message);
    }
  }

  useEffect(() => {
    loadProducts();
  }, []);

  return (
