import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { registerRootComponent } from "expo";

function App() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    AsyncStorage.getItem("cart").then((saved) => {
      if (saved !== null) setCount(Number(saved));
    });
  }, []);

  const add = () => {
    const next = count + 1;
    setCount(next);
    AsyncStorage.setItem("cart", String(next));
  };

  return (
    <View style={styles.screen}>
      <Text nativeID="count" style={styles.count}>Сагс: {count}</Text>
      <Pressable nativeID="add" style={styles.btn} onPress={add}>
        <Text style={styles.btnText}>Сагслах</Text>
      </Pressable>
    </View>
  );
}

